package com.bank.argo;

import java.util.logging.Logger;

// The Git repo ArgoCD watches. CI commits new image tags here.
public class GitSource {
    private static final Logger log = Logger.getLogger(GitSource.class.getName());
    private final String repoUrl;
    private String desiredImageTag;

    public GitSource(String repoUrl, String initialTag) {
        this.repoUrl = repoUrl;
        this.desiredImageTag = initialTag;
    }

    // CI (Jenkins/GitHub Actions) writes the new tag here after build+test.
    public void commitNewTag(String tag, String author) {
        this.desiredImageTag = tag;
        log.info(() -> "CI committed desired tag " + tag + " to " + repoUrl + " (by " + author + ")");
    }

    public String getDesiredImageTag() { return desiredImageTag; }
    public String getRepoUrl() { return repoUrl; }
}
