package com.bank.argo;

import java.util.logging.Logger;

// Traditional push: external server holds cluster creds, applies once.
public class PushPipeline {
    private static final Logger log = Logger.getLogger(PushPipeline.class.getName());
    private final String kubeconfigCredential;  // held OUTSIDE the cluster (risk)

    public PushPipeline(String kubeconfigCredential) {
        this.kubeconfigCredential = kubeconfigCredential;
    }

    public void deploy(Application app, String tag) {
        log.warning(() -> "Jenkins uses external kubeconfig credential '" + kubeconfigCredential
            + "' to kubectl apply " + tag);
        app.setLiveImageTag(tag);
        log.info(() -> "Pushed " + tag + " to " + app.getName()
            + " — ONE-SHOT, no ongoing drift correction.");
    }
}
