package com.bank.argo;

import java.util.logging.Logger;

// Pull-based: runs IN the cluster, pulls desired state from Git, reconciles.
public class ArgoCdController {
    private static final Logger log = Logger.getLogger(ArgoCdController.class.getName());
    private final GitSource git;
    private final Application app;
    private final boolean selfHeal;

    public ArgoCdController(GitSource git, Application app, boolean selfHeal) {
        this.git = git;
        this.app = app;
        this.selfHeal = selfHeal;
    }

    // One reconcile pass: compare Git desired vs cluster live, report + sync.
    public void reconcile() {
        String desired = git.getDesiredImageTag();
        String live = app.getLiveImageTag();
        if (desired.equals(live)) {
            app.setSyncStatus("Synced");
            app.setHealth("Healthy");
            log.fine(() -> app.getName() + " Synced/Healthy at " + live);
            return;
        }
        app.setSyncStatus("OutOfSync");
        app.setHealth("Progressing");
        log.warning(() -> app.getName() + " OutOfSync: desired=" + desired + " live=" + live);
        if (selfHeal) {
            app.setLiveImageTag(desired);
            app.setSyncStatus("Synced");
            app.setHealth("Healthy");
            log.info(() -> "ArgoCD synced " + app.getName() + " → " + desired
                + " (pull-based, no external creds).");
        }
    }

    // Simulate manual drift on the cluster.
    public void manualDrift(String tag) {
        app.setLiveImageTag(tag);
        app.setSyncStatus("OutOfSync");
        log.warning(() -> "Manual change drifted " + app.getName() + " to " + tag);
    }
}
