package com.bank.argo;

import java.util.logging.*;

public class ArgoCdDemo {
    private static final Logger log = Logger.getLogger(ArgoCdDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("=== Traditional PUSH (Jenkins holds cluster creds) ===");
        Application pushApp = new Application("loan-service", "loan-service:2.0.0");
        new PushPipeline("prod-kubeconfig-secret").deploy(pushApp, "loan-service:2.1.0");
        log.info(() -> "After push: live=" + pushApp.getLiveImageTag()
            + " (nothing watches for later drift)");

        log.info("=== ArgoCD PULL (in-cluster, continuous) ===");
        GitSource git = new GitSource("https://git.nbi.in/platform/gitops-repo.git", "loan-service:2.0.0");
        Application argoApp = new Application("loan-service", "loan-service:2.0.0");
        ArgoCdController argo = new ArgoCdController(git, argoApp, true);

        argo.reconcile(); // Synced
        git.commitNewTag("loan-service:2.1.0", "ci-bot");  // CI writes to Git
        argo.reconcile(); // ArgoCD pulls + syncs to 2.1.0
        argo.manualDrift("loan-service:1.9.0");            // someone edits by hand
        argo.reconcile(); // ArgoCD self-heals back to 2.1.0
        log.info(() -> "Final: " + argoApp.getName() + " " + argoApp.getSyncStatus()
            + "/" + argoApp.getHealth() + " at " + argoApp.getLiveImageTag());
    }
}
